mapper.select:
select t.min_value,t.min_value minValue,t.machine_id,t.machine_id machineId,t.max_value,t.max_value
maxValue,t.sensor_type,t.sensor_type sensorType,t.status_cd,t.status_cd
statusCd,t.units,t.community_id,t.community_id communityId,t.sensor_id,t.sensor_id sensorId
from instrument_sensor t
where 1 =1

    and t.min_value= #{minValue}


    and t.machine_id= #{machineId}


    and t.max_value= #{maxValue}


    and t.sensor_type= #{sensorType}


    and t.status_cd= #{statusCd}


    and t.units= #{units}


    and t.community_id= #{communityId}


    and t.sensor_id= #{sensorId}

order by t.create_time desc

    limit #{page}, #{row}

